using System;
using System.Collections.Generic;
using System.Drawing;
using System.Globalization;
using System.IO;
using System.Linq;
using Office=Microsoft.Office.Core;
using PowerPoint=Microsoft.Office.Interop.PowerPoint;
namespace PowerPointIntelligence.AddIn
{
    internal sealed class ChartAnnotationSpec
    {
        internal string Kind,ChartId;internal double Value;internal int Series,From,To;
        internal void Validate(){if(!ChartAnnotationPlan.Finite(Value))throw new InvalidDataException("Annotation numbers must be finite.");Guid id;if(!Guid.TryParse(ChartId,out id)||id==Guid.Empty)throw new InvalidDataException("Invalid annotation chart identity.");if(Kind=="reference"){if(!ChartAnnotationPlan.Finite(Value))throw new InvalidDataException("Use a finite reference value.");}else if(Kind=="difference"){if(Series<1||Series>100||From<1||To<1||From>10000||To>10000||From==To)throw new InvalidDataException("Choose distinct categories and a valid series.");}else throw new InvalidDataException("Unknown annotation kind.");}
        internal Dictionary<string,string> Tags(){Validate();return new Dictionary<string,string>{{"PPI_CA_SCHEMA","1"},{"PPI_CA_KIND",Kind},{"PPI_CA_CHART",ChartId},{"PPI_CA_VALUE",Value.ToString("R",CultureInfo.InvariantCulture)},{"PPI_CA_SERIES",Series.ToString(CultureInfo.InvariantCulture)},{"PPI_CA_FROM",From.ToString(CultureInfo.InvariantCulture)},{"PPI_CA_TO",To.ToString(CultureInfo.InvariantCulture)}};}
        internal static ChartAnnotationSpec Read(Func<string,string> tag){if(tag("PPI_CA_SCHEMA")!="1")throw new InvalidDataException("Unknown annotation schema.");var s=new ChartAnnotationSpec {Kind=(tag("PPI_CA_KIND")??"").ToLowerInvariant(),ChartId=tag("PPI_CA_CHART")};if(!Double.TryParse(tag("PPI_CA_VALUE"),NumberStyles.Float,CultureInfo.InvariantCulture,out s.Value)||!Int32.TryParse(tag("PPI_CA_SERIES"),NumberStyles.None,CultureInfo.InvariantCulture,out s.Series)||!Int32.TryParse(tag("PPI_CA_FROM"),NumberStyles.None,CultureInfo.InvariantCulture,out s.From)||!Int32.TryParse(tag("PPI_CA_TO"),NumberStyles.None,CultureInfo.InvariantCulture,out s.To))throw new InvalidDataException("Malformed annotation metadata.");s.Validate();return s;}
    }
    internal sealed class ChartAnnotationPlan
    {
        internal PointF Start,End;internal RectangleF Label;internal string Text;internal bool Arrow;
        private static string Number(double n){double a=Math.Abs(n);return n.ToString(a>=1000000||a>0&&a<.001?"0.###E+0":"0.###",CultureInfo.InvariantCulture);}
        internal static bool Finite(double n){return !Double.IsNaN(n)&&!Double.IsInfinity(n);}
        private static void Bounds(RectangleF p,double min,double max){if(!Finite(p.X)||!Finite(p.Y)||!Finite(p.Width)||!Finite(p.Height)||!Finite(p.Right)||!Finite(p.Bottom)||p.Width<=0||p.Height<=0||!Finite(min)||!Finite(max)||max<=min||!Finite(max-min))throw new InvalidDataException("Invalid native plot or axis bounds.");}
        internal static float Position(double value,double min,double max,float origin,float length,bool reversed){if(!Finite(value)||!Finite(min)||!Finite(max)||max<=min||!Finite(max-min)||!Finite(origin)||!Finite(length)||length<=0||value<min||value>max)throw new InvalidDataException("Annotation value lies outside the native value axis.");double t=(value-min)/(max-min);return origin+(float)((reversed?1-t:t)*length);}
        internal static ChartAnnotationPlan Reference(RectangleF p,double min,double max,double value,bool horizontal,bool reversed){Bounds(p,min,max);float v=Position(value,min,max,horizontal?p.Left:p.Top,horizontal?p.Width:p.Height,horizontal?reversed:!reversed);return new ChartAnnotationPlan {Start=horizontal?new PointF(v,p.Top):new PointF(p.Left,v),End=horizontal?new PointF(v,p.Bottom):new PointF(p.Right,v),Label=horizontal?new RectangleF(v+4,p.Top+4,105,24):new RectangleF(p.Right-110,v-26,110,24),Text=Number(value)};}
        internal static ChartAnnotationPlan Difference(RectangleF p,double min,double max,double[] values,int from,int to,bool horizontal,bool reversed,bool categoriesReversed,bool betweenCategories=true){Bounds(p,min,max);if(values==null||values.Length<2||values.Length>10000||from<1||to<1||from>values.Length||to>values.Length||from==to)throw new InvalidDataException("Choose two different existing categories.");double a=values[from-1],b=values[to-1],delta=b-a;if(!Finite(a)||!Finite(b)||!Finite(delta)||delta==0)throw new InvalidDataException("Selected points must have finite, different numeric values.");float av=Position(a,min,max,horizontal?p.Left:p.Top,horizontal?p.Width:p.Height,horizontal?reversed:!reversed),bv=Position(b,min,max,horizontal?p.Left:p.Top,horizontal?p.Width:p.Height,horizontal?reversed:!reversed);double category=betweenCategories?(to-.5)/values.Length:(to-1.0)/(values.Length-1);if(categoriesReversed)category=1-category;float cross=horizontal?p.Top+(float)(category*p.Height):p.Left+(float)(category*p.Width);return new ChartAnnotationPlan {Start=horizontal?new PointF(av,cross):new PointF(cross,av),End=horizontal?new PointF(bv,cross):new PointF(cross,bv),Label=horizontal?new RectangleF(Math.Min(av,bv),cross+5,120,24):new RectangleF(cross+7,(av+bv)/2-12,120,24),Text="Δ "+(delta>0?"+":"")+Number(delta),Arrow=true};}
    }
    internal static class ChartAnnotations
    {
        internal const string ChartTag="PPI_CA_ID";
        private sealed class Context {internal PowerPoint.Chart Chart;internal RectangleF Plot;internal double Min,Max;internal bool Horizontal,Reversed,CategoriesReversed,BetweenCategories,DateCategories;}
        private static PowerPoint.Shape Selected(PowerPoint.Application app){if(app==null||app.Presentations.Count==0)throw new InvalidOperationException("Open a presentation and select a native chart.");var s=app.ActiveWindow.Selection;if(s.Type!=PowerPoint.PpSelectionType.ppSelectionShapes||s.ShapeRange.Count!=1)throw new InvalidOperationException("Select one native chart or linked annotation.");return s.ShapeRange[1];}
        private static Context Inspect(PowerPoint.Shape shape)
        {
            if(shape.HasChart!=Office.MsoTriState.msoTrue)throw new InvalidOperationException("Select one native chart.");if(Math.Abs(shape.Rotation)>.01||shape.HorizontalFlip==Office.MsoTriState.msoTrue||shape.VerticalFlip==Office.MsoTriState.msoTrue)throw new InvalidOperationException("Rotated/flipped charts are unsupported.");var c=shape.Chart;var kind=c.ChartType;bool horizontal=kind==Office.XlChartType.xlBarClustered;if(!horizontal&&kind!=Office.XlChartType.xlColumnClustered&&kind!=Office.XlChartType.xlLine&&kind!=Office.XlChartType.xlLineMarkers&&kind!=Office.XlChartType.xlArea)throw new InvalidOperationException("Use an unstacked 2-D clustered column/bar, line or area chart. Combined, stacked, XY and 3-D charts are unsupported.");
            if(Convert.ToBoolean(c.HasAxis[PowerPoint.XlAxisType.xlValue,PowerPoint.XlAxisGroup.xlSecondary],CultureInfo.InvariantCulture))throw new InvalidOperationException("Secondary axes are ambiguous for this annotation.");var collection=(PowerPoint.SeriesCollection)c.SeriesCollection();for(int seriesIndex=1;seriesIndex<=collection.Count;seriesIndex++){PowerPoint.Series s=collection.Item(seriesIndex);if(s.AxisGroup!=PowerPoint.XlAxisGroup.xlPrimary||s.ChartType!=kind)throw new InvalidOperationException("Mixed or secondary-axis series are unsupported.");}var axis=(PowerPoint.Axis)c.Axes(PowerPoint.XlAxisType.xlValue,PowerPoint.XlAxisGroup.xlPrimary);if(axis.ScaleType!=PowerPoint.XlScaleType.xlScaleLinear)throw new InvalidOperationException("Logarithmic axes are unsupported.");var category=(PowerPoint.Axis)c.Axes(PowerPoint.XlAxisType.xlCategory,PowerPoint.XlAxisGroup.xlPrimary);var area=c.ChartArea;double width=area.Width,height=area.Height;if(!ChartAnnotationPlan.Finite(width)||!ChartAnnotationPlan.Finite(height)||width<=0||height<=0)throw new InvalidOperationException("Native chart dimensions are unavailable.");var plot=c.PlotArea;double sx=shape.Width/width,sy=shape.Height/height;var result=new Context {Chart=c,Plot=new RectangleF(shape.Left+(float)(plot.InsideLeft*sx),shape.Top+(float)(plot.InsideTop*sy),(float)(plot.InsideWidth*sx),(float)(plot.InsideHeight*sy)),Min=axis.MinimumScale,Max=axis.MaximumScale,Horizontal=horizontal,Reversed=axis.ReversePlotOrder,CategoriesReversed=category.ReversePlotOrder,BetweenCategories=category.AxisBetweenCategories,DateCategories=category.CategoryType==PowerPoint.XlCategoryType.xlTimeScale};ChartAnnotationPlan.Reference(result.Plot,result.Min,result.Max,result.Min,horizontal,result.Reversed);return result;
        }
        private static double[] Values(Context c,int index){var all=(PowerPoint.SeriesCollection)c.Chart.SeriesCollection();if(index<1||index>all.Count)throw new InvalidDataException("Series index does not exist.");object raw=all.Item(index).Values;var a=raw as Array;if(a!=null&&a.Rank!=1)throw new InvalidDataException("Native series values must be one-dimensional.");var items=a==null?new[]{raw}:a.Cast<object>().ToArray();return items.Select(v=>{if(v==null||v==DBNull.Value||v is string&&String.IsNullOrWhiteSpace((string)v))return Double.NaN;try{return Convert.ToDouble(v,CultureInfo.InvariantCulture);}catch(Exception ex) when(ex is FormatException||ex is InvalidCastException||ex is OverflowException){throw new InvalidDataException("Series contains unsupported values.",ex);}}).ToArray();}
        private static ChartAnnotationPlan Plan(Context c,ChartAnnotationSpec s){if(s.Kind=="difference"&&c.DateCategories)throw new InvalidOperationException("Date-scaled category axes are unsupported for differences.");return s.Kind=="reference"?ChartAnnotationPlan.Reference(c.Plot,c.Min,c.Max,s.Value,c.Horizontal,c.Reversed):ChartAnnotationPlan.Difference(c.Plot,c.Min,c.Max,Values(c,s.Series),s.From,s.To,c.Horizontal,c.Reversed,c.CategoriesReversed,c.BetweenCategories);}
        private static void Canvas(PowerPoint.Application app,ChartAnnotationPlan plan){float w=app.ActivePresentation.PageSetup.SlideWidth,h=app.ActivePresentation.PageSetup.SlideHeight;foreach(var p in new[]{plan.Start,plan.End,new PointF(plan.Label.Left,plan.Label.Top),new PointF(plan.Label.Right,plan.Label.Bottom)})if(!ChartAnnotationPlan.Finite(p.X)||!ChartAnnotationPlan.Finite(p.Y)||p.X<0||p.Y<0||p.X>w||p.Y>h)throw new InvalidOperationException("Annotation or label would leave the slide. Move/resize the chart or choose another category.");}
        private static PowerPoint.Shape Draw(PowerPoint.Slide slide,ChartAnnotationPlan plan,ChartAnnotationSpec spec)
        {
            PowerPoint.Shape line=null,label=null,group=null;try{line=slide.Shapes.AddLine(plan.Start.X,plan.Start.Y,plan.End.X,plan.End.Y);line.Line.ForeColor.RGB=0x795234;line.Line.Weight=1.5f;if(plan.Arrow){line.Line.BeginArrowheadStyle=Office.MsoArrowheadStyle.msoArrowheadTriangle;line.Line.EndArrowheadStyle=Office.MsoArrowheadStyle.msoArrowheadTriangle;}else line.Line.DashStyle=Office.MsoLineDashStyle.msoLineDash;label=slide.Shapes.AddTextbox(Office.MsoTextOrientation.msoTextOrientationHorizontal,plan.Label.X,plan.Label.Y,plan.Label.Width,plan.Label.Height);label.TextFrame.TextRange.Text=plan.Text;label.TextFrame.TextRange.Font.Name="Segoe UI";label.TextFrame.TextRange.Font.Size=12;label.TextFrame2.AutoSize=Office.MsoAutoSize.msoAutoSizeTextToFitShape;label.TextFrame.MarginLeft=label.TextFrame.MarginRight=label.TextFrame.MarginTop=label.TextFrame.MarginBottom=0;label.Fill.Visible=Office.MsoTriState.msoFalse;label.Line.Visible=Office.MsoTriState.msoFalse;group=slide.Shapes.Range(new object[]{line.Name,label.Name}).Group();group.Name="ppi_annotation_"+Guid.NewGuid().ToString("N");foreach(var pair in spec.Tags())group.Tags.Add(pair.Key,pair.Value);group.AlternativeText="Chart-linked "+spec.Kind+"; Refresh Annotation regenerates geometry and default styling after chart changes.";return group;}catch(Exception original){bool cleaned=true;if(group!=null){try{group.Delete();}catch{cleaned=false;}}else{if(label!=null)try{label.Delete();}catch{cleaned=false;}if(line!=null)try{line.Delete();}catch{cleaned=false;}}if(!cleaned)throw new InvalidOperationException("Annotation creation failed and cleanup was incomplete. Use PowerPoint Undo.",original);throw;}
        }
        internal static PowerPoint.Shape Reference(PowerPoint.Application app,double value){return Insert(app,new ChartAnnotationSpec {Kind="reference",Value=value});}
        internal static PowerPoint.Shape Difference(PowerPoint.Application app,int series,int from,int to){return Insert(app,new ChartAnnotationSpec {Kind="difference",Series=series,From=from,To=to});}
        private static PowerPoint.Shape Insert(PowerPoint.Application app,ChartAnnotationSpec spec)
        {
            var chart=Selected(app);var c=Inspect(chart);string old=chart.Tags[ChartTag];Guid id;string identity=old;if(!Guid.TryParse(identity,out id)||id==Guid.Empty)identity=Guid.NewGuid().ToString("D");spec.ChartId=identity;spec.Validate();var plan=Plan(c,spec);Canvas(app,plan);var slide=app.ActiveWindow.View.Slide as PowerPoint.Slide;if(slide==null)throw new InvalidOperationException("Use Normal view.");if(slide.Shapes.Cast<PowerPoint.Shape>().Count(s=>s.HasChart==Office.MsoTriState.msoTrue&&String.Equals(s.Tags[ChartTag],identity,StringComparison.OrdinalIgnoreCase))>1)throw new InvalidOperationException("Copied chart identity is ambiguous; preserve objects and choose a chart with a unique identity.");app.StartNewUndoEntry();PowerPoint.Shape result=null;try{result=Draw(slide,plan,spec);chart.Tags.Add(ChartTag,identity);result.Select();return result;}catch(Exception original){bool cleaned=true;if(result!=null)try{result.Delete();}catch{cleaned=false;}try{if(String.IsNullOrEmpty(old))chart.Tags.Delete(ChartTag);else chart.Tags.Add(ChartTag,old);}catch{cleaned=false;}if(!cleaned)throw new InvalidOperationException("Annotation creation failed and cleanup was incomplete. Use PowerPoint Undo.",original);throw;}
        }
        internal static PowerPoint.Shape RefreshSelected(PowerPoint.Application app)
        {
            var original=Selected(app);var spec=ChartAnnotationSpec.Read(k=>original.Tags[k]);var slide=app.ActiveWindow.View.Slide as PowerPoint.Slide;if(slide==null)throw new InvalidOperationException("Use Normal view.");var matches=slide.Shapes.Cast<PowerPoint.Shape>().Where(s=>s.HasChart==Office.MsoTriState.msoTrue&&String.Equals(s.Tags[ChartTag],spec.ChartId,StringComparison.OrdinalIgnoreCase)).ToArray();if(matches.Length!=1)throw new InvalidOperationException("The chart is missing or copied chart identity is ambiguous. Preserve objects and create a new annotation.");var plan=Plan(Inspect(matches[0]),spec);Canvas(app,plan);app.StartNewUndoEntry();var replacement=Draw(slide,plan,spec);try{original.Delete();}catch(Exception ex){throw new InvalidOperationException("Refresh created a replacement but could not confirm removal of the previous annotation. The replacement was retained; inspect both objects or use PowerPoint Undo.",ex);}replacement.Select();return replacement;
        }
    }
}
